 $('#fiscalProfileForm').onsubmit=e=>{e.preventDefault();const p=Object.fromEntries(new FormData(e.currentTarget));p.country=p.country.trim().toUpperCase();p.province=p.province.trim().toUpperCase();p.vatNumber=p.vatNumber.replace(/\s+/g,'');p.fiscalCode=p.fiscalCode.replace(/\s+/g,'').toUpperCase();p.recipientCode=p.recipientCode.trim().toUpperCase();db.settings.fiscalProfile=p;persist();render();toast('Dati attività salvati sul dispositivo')};
