 $('#settingsForm').onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.currentTarget));values.lowStockThreshold=Math.min(999999,Math.max(0,Math.floor(Number(values.lowStockThreshold)||0)));Object.assign(db.settings,values);document.documentElement.style.setProperty('--red',db.settings.accent);persist();render();toast('Impostazioni salvate')};
