 const configuredRate=db.settings.taxSetup?.defaultVatRate??'';
 const natureOptions=[['','Seleziona Natura IVA'],['N1','N1 · Escluse ex art. 15'],['N2.1','N2.1 · Non soggette art. 7-7-septies'],['N2.2','N2.2 · Altre non soggette'],['N3.1','N3.1 · Non imponibili esportazioni'],['N3.2','N3.2 · Cessioni intracomunitarie'],['N3.3','N3.3 · Cessioni verso San Marino'],['N3.4','N3.4 · Operazioni assimilate'],['N3.5','N3.5 · A seguito di dichiarazioni d’intento'],['N3.6','N3.6 · Altre non imponibili'],['N4','N4 · Esenti'],['N5','N5 · Regime del margine'],['N6.1','N6.1 · Inversione contabile rottami'],['N6.2','N6.2 · Inversione contabile oro'],['N6.3','N6.3 · Inversione contabile subappalto'],['N6.4','N6.4 · Inversione contabile cessione fabbricati'],['N6.5','N6.5 · Inversione contabile telefoni'],['N6.6','N6.6 · Inversione contabile elettronica'],['N6.7','N6.7 · Inversione contabile edilizia'],['N6.8','N6.8 · Inversione contabile altri settori'],['N6.9','N6.9 · Altri casi'],['N7','N7 · IVA assolta in altro Stato UE']].map(([v,l])=>`<option value="${v}" ${doc.vatNature===v?'selected':''}>${l}</option>`).join('');
