function startDocument(){showModal('Nuovo documento','Compila i dati. Per esportare XML FatturaPA servono anche dati completi del cliente e dell’emittente.',documentFields(),'Salva bozza',d=>db.documents.push({id:makeId('DOC'),number:`D-${String(db.documents.length+1).padStart(4,'0')}`,...d,quantity:Number(d.quantity),total:Number(d.total),vatRate:d.vatRate===''?null:Number(d.vatRate),date:new Date(d.date).toISOString()}));}
function editDocument(id){const doc=db.documents.find(x=>x.id===id);if(!doc)return;if(['inviata','accettata'].includes(doc.sdi?.status)){toast('Documento già inviato: non modificarlo. Per correzioni usa la procedura fiscale prevista.');return}showModal('Modifica documento',`Riferimento ${esc(doc.number)} · le modifiche a una bozza annullano l’XML già preparato.`,documentFields(doc),'Salva modifiche',values=>{const now=new Date().toISOString(),history=doc.sdi?.history||[];Object.assign(doc,values,{quantity:Number(values.quantity),total:Number(values.total),vatRate:values.vatRate===''?null:Number(values.vatRate),date:new Date(values.date).toISOString(),xml:null,downloadName:null});if(String(doc.type||'').includes('Fattura'))doc.sdi={status:'bozza',history:[...history,{status:'modificata',updatedAt:now}]};else delete doc.sdi;});}function exportInvoiceXml(id){const d=db.documents.find(x=>x.id===id);if(!d||!String(d.type||'').includes('Fattura'))return;try{const source={...d,customer:d.customer||d.customerName||d.clientName||d.cliente||''},result=window.fatturapa.generate(source,db.settings.fiscalProfile||{});d.xml=result.xml;d.downloadName=result.fileName;if(!['accettata','inviata'].includes(d.sdi?.status))d.sdi={...(d.sdi||{}),status:'da_inviare',xmlExportedAt:new Date().toISOString()};persist();const url=URL.createObjectURL(new Blob([result.xml],{type:'application/xml;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=result.fileName;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);render();toast('XML aggiornato e scaricato. Verifica i dati prima di trasmetterlo al SdI')}catch(error){const message=error.message||'Impossibile generare XML FatturaPA';toast(message);if(/cliente/i.test(message))editDocument(id)}}function printDoc(id){const d=db.documents.find(x=>x.id===id);if(!d)return;const f=db.settings.fiscalProfile||{},status=d.sdi?.status||'bozza';const label=status==='accettata'?'COPIA DI CORTESIA · esito positivo registrato dal SdI':status==='scartata'?'SCARTO SDI · il documento non risulta emesso':status==='inviata'?'XML inviato · in attesa di esito SdI':status==='da_inviare'?'XML preparato · da trasmettere al SdI':'BOZZA OPERATIVA · non trasmessa al SdI e non valida come fattura elettronica';const rows=[['Documento',d.number||''],['Data',d.date?dateFmt(d.date):''],['Tipo',d.type||''],['Emittente',f.legalName||db.settings.shopName||''],['Partita IVA emittente',f.vatNumber||''],['Cliente',d.customer||''],['Partita IVA / codice fiscale cliente',[d.vatNumber,d.fiscalCode].filter(Boolean).join(' · ')],['Indirizzo cliente',[d.address,d.postalCode,d.city,d.province,d.customerCountry].filter(Boolean).join(', ')],['Descrizione',d.description||''],['Quantità',d.quantity??''],['Totale',euro(d.total)],['Note',d.notes||'']];const html=`<!doctype html><html lang="it"><meta charset="utf-8"><title>${esc(d.number||'Documento')} · ${esc(db.settings.shopName)}</title><style>body{font:14px Arial;color:#222;margin:42px}header{display:flex;justify-content:space-between;border-bottom:2px solid #e24842;padding-bottom:18px}h1{font-size:24px;margin:0}small{color:#777}.row{display:grid;grid-template-columns:180px 1fr;padding:10px 0;border-bottom:1px solid #ddd}.row b{color:#555}.notice{margin-top:32px;padding:14px;border:1px solid #e4c77c;color:#805d17;background:#fffaf0;font-weight:bold}@media print{body{margin:20mm}}</style><header><div><h1>${esc(db.settings.shopName||'POKEBRICKS')}</h1><small>${esc(f.legalName||'')}</small></div><div><b>${esc(d.number||'Documento')}</b><br><small>${esc(d.type||'')} · ${d.date?dateFmt(d.date):''}</small></div></header><section style="margin-top:24px">${rows.map(([label,value])=>`<div class="row"><b>${esc(label)}</b><span>${esc(value)}</span></div>`).join('')}</section><div class="notice">${label}</div></html>`;if(!window.pokebricks?.printDocument){toast('Funzione di stampa non disponibile in questa build');return}window.pokebricks.printDocument(html).then(result=>{if(!result.success&&result.reason!=='Print job canceled')toast('Stampa non riuscita: '+(result.reason||'errore del sistema'))}).catch(error=>toast('Impossibile avviare la stampa: '+error.message))}document.addEventListener('click',e=>{const nav=e.target.closest('[data-page]');if(nav){current=nav.dataset.page;render();return}const b=e.target.closest('[data-action]');if(!b)return;switch(b.dataset.action){case'new-product':startProduct();break;case'new-sale':startSale();break;case'new-document':startDocument();break;case'return-sale':startReturn(b.dataset.id);break;case'show-sale-returns':showSaleReturns(b.dataset.id);break;case'close-modal':closeModal();break;case'export-report':exportMonthlyReport();break;case'product-csv-import':$('#productCsvFile')?.click();break;case'product-csv-template':downloadProductCsvTemplate();break;case'choose-backup':$('#backupFile')?.click();break;case'show-stock-alerts':showStockAlerts();break;case'show-update-notifications':showUpdateNotifications();break;case'close-notifications':closeModal();break;case'close-stock-alerts':$('#modal').classList.add('hidden');break;case'open-alert-catalog':$('#modal').classList.add('hidden');current='products';render();break;case'delete-product':db.products=db.products.filter(p=>p.id!==b.dataset.id);persist();render();toast('Prodotto rimosso');break;case'export-invoice-xml':exportInvoiceXml(b.dataset.id);break;case'update-sdi-status':updateSdiStatus(b.dataset.id);break;case'export-invoice-register':exportInvoiceRegister();break;case'edit-doc':editDocument(b.dataset.id);break;case'print-doc':printDoc(b.dataset.id);break;case'export':{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(db,null,2)],{type:'application/json'}));a.download=`pokebricks-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Copia dati esportata');break}}});
document.addEventListener('change',e=>{if(e.target.matches('#productCsvFile'))handleProductCsv(e.target)});
document.addEventListener('change',async e=>{if(!e.target.matches('#backupFile'))return;const input=e.target,file=input.files?.[0];if(!file)return;try{const imported=JSON.parse(await file.text());const valid=imported&&typeof imported==='object'&&!Array.isArray(imported)&&imported.settings&&typeof imported.settings==='object'&&!Array.isArray(imported.settings)&&Array.isArray(imported.products)&&Array.isArray(imported.sales)&&Array.isArray(imported.documents)&&[...imported.products,...imported.sales,...imported.documents].every(item=>item&&typeof item==='object'&&!Array.isArray(item));if(!valid)throw new Error('Il file selezionato non ha il formato di un backup POKEBRICKS.');const summary=`Il backup contiene ${imported.products.length} prodotti, ${imported.sales.length} vendite e ${imported.documents.length} documenti.\n\nI dati attuali saranno salvati in una copia di sicurezza prima del ripristino. Vuoi continuare?`;if(!window.confirm(summary))return;await window.pokebricks.restore(imported);db=await window.pokebricks.load();document.documentElement.style.setProperty('--red',db.settings.accent||'#e24842');render();toast('Backup ripristinato; copia di sicurezza creata')}catch(error){toast(error.message||'Impossibile ripristinare il backup')}finally{input.value=''}});
document.addEventListener('change',e=>{if(e.target.matches('#reportMonth')&&/^\d{4}-\d{2}$/.test(e.target.value)){reportMonth=e.target.value;render()}});
document.addEventListener('input',e=>{if(!e.target.matches('[data-search]'))return;const q=e.target.value.toLowerCase();$$('#page tbody tr').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(q));});$('#closeModal').onclick=closeModal;$('#modal').addEventListener('click',e=>{if(e.target.id==='modal')closeModal()});$('#today').textContent=new Date().toLocaleDateString('it-IT',{weekday:'short',day:'numeric',month:'short',year:'numeric'});
function updateNotesText(notes){const entries=Array.isArray(notes)?notes.map(n=>typeof n==='string'?n:(n?.note||'')).filter(Boolean):[typeof notes==='string'?notes:''];let text=entries.join('\n\n');if(/<\/?(h[1-6]|p|ul|ol|li|br|div)\b/i.test(text)){text=text.replace(/<br\s*\/?\s*>/gi,'\n').replace(/<li\b[^>]*>/gi,'• ').replace(/<\/(h[1-6]|p|li|div|ul|ol)\s*>/gi,'\n');const parsed=new DOMParser().parseFromString(text,'text/html');text=parsed.body.textContent||''}return text.replace(/^[ \t]*#{1,6}[ \t]*/gm,'').replace(/^[ \t]*[-*][ \t]+/gm,'• ').replace(/`/g,'').replace(/[ \t]+\n/g,'\n').replace(/\n{3,}/g,'\n\n').trim()}
function showUpdateNotes(notes){const box=$('#updateNotes'),text=updateNotesText(notes);box.textContent=text;box.classList.toggle('hidden',!text)}
function updateStatus(s){const overlay=$('#updateOverlay');if(s.state==='available'){toast(`Aggiornamento ${s.version} disponibile · download in corso`);$('#updateTitle').textContent=`Aggiornamento ${s.version} disponibile`;$('#updateText').textContent='Novità di questa versione e posizione della nuova funzione:';showUpdateNotes(s.releaseNotes);overlay.classList.remove('hidden')}if(s.state==='downloaded'){$('#updateTitle').textContent='Aggiornamento pronto';$('#updateText').textContent=`Versione ${s.version} scaricata e pronta da installare.`;showUpdateNotes(s.releaseNotes);$('#progressBar').style.width='100%';$('#progressPercent').textContent='100%';$('#progressLabel').textContent='Download completato';overlay.classList.remove('hidden');let n=5;const note=$('#restartNote');note.classList.remove('hidden');note.textContent=`Riavvio automatico tra ${n} secondi…`;const t=setInterval(()=>{n--;note.textContent=n>0?`Riavvio automatico tra ${n} secondi…`:'Riavvio in corso…';if(n<=0){clearInterval(t);window.pokebricks.installUpdate()}},1000)}if(s.state==='error'){const detail=String(s.message||'Errore non specificato').replace(/\s+/g,' ').slice(0,180);if(!overlay.classList.contains('hidden')){$('#updateTitle').textContent='Aggiornamento non riuscito';$('#updateText').textContent=`${detail} L’app continuerà a funzionare con la versione installata.`}else toast(`Aggiornamento non riuscito: ${detail}`)} }
document.addEventListener('click',e=>{const nav=e.target.closest('[data-page]');if(nav?.dataset.page==='tiktok')loadTikTokStatus();const action=e.target.closest('[data-action]')?.dataset.action;if(action==='tiktok-connect')connectTikTok();if(action==='tiktok-select-shop')chooseTikTokShop();if(action==='tiktok-sync')syncTikTokOrders();if(action==='tiktok-clear')clearTikTok()});
document.addEventListener('submit',e=>{if(e.target?.id==='tiktokCredentialsForm')saveTikTokCredentials(e)});
document.addEventListener('change',async e=>{if(e.target?.id==='tiktokAutoSync'){try{tiktokStatus=await window.pokebricks.tiktokAutoSync(e.target.checked);render();if(e.target.checked)syncTikTokOrders()}catch(error){toast(error.message||'Impostazione sincronizzazione non riuscita');loadTikTokStatus()}return}if(!e.target?.matches('.tiktok-match'))return;const order=db.tiktokOrders.find(item=>item.id===e.target.dataset.orderId),line=order?.items.find(item=>item.id===e.target.dataset.itemId);if(!line)return;const before=JSON.stringify(db);try{line.productId=e.target.value||null;const selected=db.products.find(product=>product.id===line.productId);if(selected)db.tiktokMappings[tikTokMappingKey(line)]=selected.id;reconcileTikTokOrders([]);await window.pokebricks.save(db);render();toast(line.saleId?'Vendita registrata e scorte aggiornate':'Associazione prodotto salvata')}catch(error){db=JSON.parse(before);render();toast(error.message||'Associazione prodotto non riuscita')}});
window.pokebricks.onUpdateStatus(updateStatus);window.pokebricks.onUpdateProgress(p=>{const overlay=$('#updateOverlay');overlay.classList.remove('hidden');$('#updateTitle').textContent='Download aggiornamento';$('#updateText').textContent='La tua area di lavoro resterà salvata in modo sicuro.';$('#progressBar').style.width=`${p.percent}%` ;$('#progressPercent').textContent=`${p.percent}%`;$('#progressLabel').textContent=`${(p.transferred/1048576).toFixed(1)} MB di ${(p.total/1048576).toFixed(1)} MB`});
window.pokebricks.load().then(async data=>{db=data;db.tiktokOrders=Array.isArray(db.tiktokOrders)?db.tiktokOrders:[];db.tiktokMappings=db.tiktokMappings&&typeof db.tiktokMappings==='object'?db.tiktokMappings:{};document.documentElement.style.setProperty('--red',db.settings.accent||'#e24842');render();await loadTikTokStatus();if(tiktokStatus?.autoSync&&tiktokStatus?.selectedShop)syncTikTokOrders();setInterval(()=>{if(tiktokStatus?.autoSync&&tiktokStatus?.selectedShop)syncTikTokOrders()},5*60*1000)}).catch(()=>{$('#page').innerHTML='<div class="empty"><b>Impossibile leggere i dati locali</b>Riprova ad aprire l’app.</div>'});
